// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;

import org.junit.jupiter.api.Test;

/**
 * Guards the zero-allocation runtime feedback publication path against Mockito instrumentation leaking across test
 * classes.
 * <p>
 * Mockito's inline mock maker retransforms the bytecode of every class it mocks or spies (and of that class's
 * supertypes) for the rest of the forked test JVM. From then on every call on an ordinary instance of that class first
 * asks Mockito whether the receiver is a mock, which allocates lookup keys. A single {@code mock(...)} or
 * {@code spy(...)} of a publication-path class therefore makes allocation assertions such as
 * {@code LmdbRuntimeFeedbackTargetTest#preboundOpenCloseAndRootPublicationAllocateNoLearningObjects} fail depending on
 * test class order. Tests observe or stub these classes through package-private hooks (for example
 * {@code LmdbOperatorFeedbackStats.setLearnedStateObserver}) or hand-written subclasses instead.
 */
class LmdbPublicationPathMockingArchitectureTest {

	/**
	 * Classes whose methods run while runtime feedback is opened, closed, published or released, plus the feedback
	 * interfaces whose default methods that path calls.
	 */
	static final List<String> PUBLICATION_PATH_TYPES = List.of(
			"LmdbOperatorFeedbackStats",
			"LmdbFilterSelectivityStats",
			"FrontierLearningModel",
			"PlanLifecycleStore",
			"RuntimeFeedbackContract",
			"RuntimeFeedbackAccumulator",
			"RuntimeFeedbackTarget",
			"InvocationAggregateView");

	private static final String MOCKING_CALL = "(?<![\\w$])(?:Mockito\\s*\\.\\s*)?(?:mock|spy|mockStatic|mockConstruction"
			+ "|mockConstructionWithAnswer)\\s*\\(";
	private static final String TYPE_ARGUMENTS = "(?:\\s*<[^;{}()]*>)?";

	@Test
	void testSourcesNeverMockOrSpyPublicationPathClasses() throws IOException {
		Path testRoot = testJavaRoot();
		assertTrue(Files.isDirectory(testRoot), "missing LMDB test sources: " + testRoot);
		List<String> violations = new ArrayList<>();
		try (Stream<Path> files = Files.walk(testRoot)) {
			for (Path file : files.filter(path -> path.toString().endsWith(".java")).sorted().toList()) {
				if (file.getFileName().toString().equals(getClass().getSimpleName() + ".java")) {
					continue;
				}
				for (String finding : findPublicationPathMocking(Files.readString(file))) {
					violations.add(testRoot.relativize(file) + ": " + finding);
				}
			}
		}
		assertEquals(List.of(), violations,
				"Mockito mocks/spies of publication-path classes retransform them for the whole test JVM and make "
						+ "runtime feedback publication allocate in every later test; use a package-private "
						+ "observer hook or a hand-written subclass instead");
	}

	@Test
	void detectorRecognisesEveryMockingShape() {
		assertDetected("LmdbFilterSelectivityStats stats = spy(real);");
		assertDetected("LmdbFilterSelectivityStats real = field();\nvar failing = Mockito.spy(real);");
		assertDetected("private LmdbFilterSelectivityStats filters;\nvoid setUp() { filters = spy(realFilters()); }");
		assertDetected("LmdbOperatorFeedbackStats stats = mock(LmdbOperatorFeedbackStats.class);");
		assertDetected("var contract = Mockito.mock(org.eclipse.rdf4j.query.algebra.feedback.RuntimeFeedbackContract"
				+ ".class, RETURNS_DEEP_STUBS);");
		assertDetected("@Mock\n\tprivate LmdbFilterSelectivityStats filters;");
		assertDetected("@Spy private final PlanLifecycleStore lifecycle = new PlanLifecycleStore();");
		assertDetected("void test(@Mock RuntimeFeedbackTarget target) {}");
		assertDetected("FrontierLearningModel model = spy(new FrontierLearningModel());");
		assertDetected("var accumulator = (RuntimeFeedbackAccumulator) spy(accumulator());");
		assertDetected("try (var mocked = mockConstruction(PlanLifecycleStore.class)) {}");
		assertDetected("List<InvocationAggregateView> views = List.of(mock(InvocationAggregateView.class));");

		assertNotDetected("LmdbFilterSelectivityStats stats = new LmdbFilterSelectivityStats(path, triples, values);");
		assertNotDetected("TripleStore tripleStore = spy(originalTripleStore);");
		assertNotDetected("ValueStore valueStore = mock(ValueStore.class);");
		assertNotDetected("@Mock\n\tprivate LmdbStatisticsService statistics;");
		assertNotDetected("// never spy(LmdbOperatorFeedbackStats.class) here\nint x = 1;");
		assertNotDetected("/* a spy(stats) of LmdbFilterSelectivityStats stats retransforms */ int x = 1;");
		assertNotDetected("String hint = \"mock(RuntimeFeedbackContract.class)\";");
		assertNotDetected("LmdbOperatorFeedbackStats stats = open();\nverify(stats).reset();");
	}

	static List<String> findPublicationPathMocking(String source) {
		String code = stripCommentsAndLiterals(source);
		String type = "\\b(?:[\\w$]+\\s*\\.\\s*)*(" + String.join("|", PUBLICATION_PATH_TYPES) + ")\\b";
		Set<String> findings = new LinkedHashSet<>();

		collect(findings, code, MOCKING_CALL + "\\s*" + type + "\\s*\\.\\s*class\\b", "mocks %s.class");
		collect(findings, code, MOCKING_CALL + "\\s*new\\s+" + type, "spies a new %s");
		collect(findings, code, "@(?:Mock|Spy)\\b(?:\\s*\\([^)]*\\))?(?:\\s+(?:@[\\w.]+|final|private|protected"
				+ "|public|static|transient|volatile))*\\s+" + type + TYPE_ARGUMENTS + "\\s+[\\w$]+",
				"declares an @Mock/@Spy %s");
		collect(findings, code, "\\(\\s*" + type + TYPE_ARGUMENTS + "\\s*\\)\\s*" + MOCKING_CALL,
				"casts a Mockito mock/spy to %s");

		Matcher declarations = Pattern.compile(type + TYPE_ARGUMENTS + "\\s+([\\w$]+)\\s*[;=,)]").matcher(code);
		Map<String, String> declaredTypeByName = new LinkedHashMap<>();
		while (declarations.find()) {
			declaredTypeByName.putIfAbsent(declarations.group(2), declarations.group(1));
		}
		for (Map.Entry<String, String> declared : declaredTypeByName.entrySet()) {
			String name = "(" + Pattern.quote(declared.getKey()) + ")";
			collect(findings, code, MOCKING_CALL + "\\s*" + name + "\\s*[,)]",
					"mocks or spies " + declared.getValue() + " variable %s");
			collect(findings, code, "(?<![\\w$.])" + name + "\\s*=\\s*" + MOCKING_CALL,
					"assigns a Mockito mock/spy to " + declared.getValue() + " variable %s");
		}
		return List.copyOf(findings);
	}

	private static void collect(Set<String> findings, String code, String regex, String message) {
		Matcher matcher = Pattern.compile(regex).matcher(code);
		while (matcher.find()) {
			findings.add("line " + lineOf(code, matcher.start()) + ": " + String.format(message, matcher.group(1)));
		}
	}

	private static int lineOf(String code, int offset) {
		int line = 1;
		for (int index = 0; index < offset; index++) {
			if (code.charAt(index) == '\n') {
				line++;
			}
		}
		return line;
	}

	/**
	 * Blanks comments and the contents of string, text-block and character literals so that prose about mocking (like
	 * this class's own documentation) is never reported, while keeping every code token and line break in place.
	 */
	static String stripCommentsAndLiterals(String source) {
		StringBuilder code = new StringBuilder(source.length());
		int index = 0;
		while (index < source.length()) {
			char current = source.charAt(index);
			char next = index + 1 < source.length() ? source.charAt(index + 1) : '\0';
			if (current == '/' && next == '/') {
				while (index < source.length() && source.charAt(index) != '\n') {
					index++;
				}
			} else if (current == '/' && next == '*') {
				int end = source.indexOf("*/", index + 2);
				int stop = end < 0 ? source.length() : end + 2;
				code.append(' ').append(lineBreaks(source, index, stop));
				index = stop;
			} else if (source.startsWith("\"\"\"", index)) {
				int end = source.indexOf("\"\"\"", index + 3);
				int stop = end < 0 ? source.length() : end + 3;
				code.append("\"\"").append(lineBreaks(source, index, stop));
				index = stop;
			} else if (current == '"' || current == '\'') {
				index++;
				while (index < source.length() && source.charAt(index) != current) {
					index += source.charAt(index) == '\\' ? 2 : 1;
				}
				index++;
				code.append(current).append(current);
			} else {
				code.append(current);
				index++;
			}
		}
		return code.toString();
	}

	private static String lineBreaks(String source, int from, int to) {
		return "\n".repeat((int) source.substring(from, to).chars().filter(character -> character == '\n').count());
	}

	private static void assertDetected(String snippet) {
		assertFalse(findPublicationPathMocking(snippet).isEmpty(), () -> "not detected: " + snippet);
	}

	private static void assertNotDetected(String snippet) {
		List<String> findings = findPublicationPathMocking(snippet);
		assertTrue(findings.isEmpty(), () -> "false positive " + findings.stream()
				.collect(Collectors.joining(", ")) + " in: " + snippet);
	}

	private static Path testJavaRoot() {
		Path moduleRoot = Path.of("core/sail/lmdb/src/test/java");
		return Files.isDirectory(moduleRoot) ? moduleRoot : Path.of("src/test/java");
	}
}
